#!/usr/bin/env node
/**
 * Generates the per-route shim pages and the 404 page.
 *
 * The site is a single index.html; GitHub Pages has no rewrite rules, so each
 * route folder holds a tiny page that fetches the real document, injects a
 * <base> plus route-specific metadata, and writes it out. Keeping that logic
 * in one template means the ten generated files never drift apart.
 *
 * Run after changing routing or metadata:
 *   node tools/build-routes.mjs
 *
 * Generated files carry a GENERATED header. Edit this file, not them.
 */

import { writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const ORIGIN = "https://rajfirke.github.io/Portfolio";

const ROUTES = {
  aboutme: {
    title: "Raj Firke — About",
    description:
      "Raj Firke is a Software Engineer (AI) at Red Hat working on agentic systems, LLM evaluation, and chain-of-thought monitoring.",
  },
  about: {
    title: "Raj Firke — About",
    description:
      "Raj Firke is a Software Engineer (AI) at Red Hat working on agentic systems, LLM evaluation, and chain-of-thought monitoring.",
    alias: true,
    canonical: "aboutme",
  },
  experience: {
    title: "Raj Firke — Experience",
    description:
      "Work history across Red Hat, Persistent Systems, BrainChain, PCCOE, and PHN Technology.",
  },
  skills: {
    title: "Raj Firke — Skills",
    description:
      "Skills across AI and machine learning, agentic AI, backend and data, cloud and DevOps, and developer tooling.",
  },
  projects: {
    title: "Raj Firke — Projects",
    description:
      "Open-source and research projects including Provena, Repo Time Machine, GreenBench, and Smart India Hackathon 2022.",
  },
  research: {
    title: "Raj Firke — Research",
    description:
      "Publications at EMNLP 2026, ICCUBEA 2026, ICTIS 2025, and IJERT, plus two patents.",
  },
  opensource: {
    title: "Raj Firke — Open Source",
    description:
      "Maintainer of Provena and active contributor to PyTorch and vLLM.",
  },
  education: {
    title: "Raj Firke — Education",
    description:
      "B.Tech in Computer Engineering from PCCOE, Pune, with earlier schooling in Jalgaon.",
  },
  certificates: {
    title: "Raj Firke — Certificates",
    description:
      "Certifications from Google, AWS, Red Hat, IIT Bombay, LinkedIn, and MinnaLearn.",
  },
};

const GENERATED = "<!-- GENERATED by tools/build-routes.mjs — do not edit by hand -->";

// Same inline favicon as index.html. Without it the browser requests
// /favicon.ico before the shim's fetch lands, producing a 404 per page view.
const FAVICON =
  "<link rel=\"icon\" type=\"image/svg+xml\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0%25' y1='0%25' x2='100%25' y2='100%25'%3E%3Cstop offset='0%25' stop-color='%23a855f7'/%3E%3Cstop offset='100%25' stop-color='%233b82f6'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='100' height='100' rx='20' fill='%23111'/%3E%3Ctext x='50' y='68' text-anchor='middle' font-family='system-ui,sans-serif' font-weight='800' font-size='48' fill='url(%23g)'%3ERF%3C/text%3E%3C/svg%3E\">";

function escapeAttr(value) {
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/"/g, "&quot;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function routeShim(slug, meta) {
  const title = escapeAttr(meta.title);
  const description = escapeAttr(meta.description);

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${title}</title>
  ${FAVICON}
  <meta name="description" content="${description}">
  <meta property="og:title" content="${title}">
  <meta property="og:description" content="${description}">
  <meta name="twitter:title" content="${title}">
  <meta name="twitter:description" content="${description}">
  <meta name="robots" content="index, follow">
  <style>html, body { margin: 0; background: #000; }</style>
  ${GENERATED}
  <script>
    (function () {
      var ROUTE = ${JSON.stringify(slug)};
      var TITLE = ${JSON.stringify(meta.title)};
      var DESCRIPTION = ${JSON.stringify(meta.description)};

      var parts = location.pathname.split("/").filter(Boolean);
      if (parts.length && /index\\.html?$/i.test(parts[parts.length - 1])) parts.pop();
      if (parts[parts.length - 1] === ROUTE) parts.pop();
      var root = "/" + parts.join("/");
      if (root.charAt(root.length - 1) !== "/") root += "/";
      var canonical = location.origin + root + ${JSON.stringify(meta.canonical || slug)};

      function esc(value) {
        return String(value)
          .replace(/&/g, "&amp;")
          .replace(/"/g, "&quot;")
          .replace(/</g, "&lt;")
          .replace(/>/g, "&gt;");
      }

      function applyMeta(html) {
        var t = esc(TITLE);
        var d = esc(DESCRIPTION);
        var c = esc(canonical);
        html = html.replace(/<title>[\\s\\S]*?<\\/title>/i, "<title>" + t + "</title>");
        html = html.replace(
          /<meta name="description" content="[^"]*">/i,
          '<meta name="description" content="' + d + '">'
        );
        html = html.replace(
          /<meta property="og:title" content="[^"]*">/i,
          '<meta property="og:title" content="' + t + '">'
        );
        html = html.replace(
          /<meta property="og:description" content="[^"]*">/i,
          '<meta property="og:description" content="' + d + '">'
        );
        html = html.replace(
          /<meta property="og:url" content="[^"]*">/i,
          '<meta property="og:url" content="' + c + '">'
        );
        html = html.replace(
          /<meta name="twitter:title" content="[^"]*">/i,
          '<meta name="twitter:title" content="' + t + '">'
        );
        html = html.replace(
          /<meta name="twitter:description" content="[^"]*">/i,
          '<meta name="twitter:description" content="' + d + '">'
        );
        html = html.replace(
          /<link rel="canonical" href="[^"]*">/i,
          '<link rel="canonical" href="' + c + '">'
        );
        return html;
      }

      function showError() {
        var p = document.createElement("p");
        p.style.cssText = "color:#fff;font-family:system-ui,sans-serif;padding:2rem";
        p.textContent = "This page could not be loaded.";
        var a = document.createElement("a");
        a.href = root;
        a.textContent = " Go home";
        a.style.color = "#c4b5fd";
        p.appendChild(a);
        document.body.appendChild(p);
      }

      fetch(root + "index.html", { credentials: "same-origin" })
        .then(function (res) {
          if (!res.ok) throw new Error("missing index");
          return res.text();
        })
        .then(function (html) {
          html = applyMeta(html);
          if (!/<base[\\s/>]/i.test(html)) {
            html = html.replace(/<head([^>]*)>/i, '<head$1><base href="' + root + '">');
          }
          document.open();
          document.write(html);
          document.close();
        })
        .catch(showError);
    })();
  </script>
</head>
<body></body>
</html>
`;
}

function notFoundPage() {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Page not found — Raj Firke</title>
  ${FAVICON}
  <meta name="robots" content="noindex">
  ${GENERATED}
  <style>
    :root { color-scheme: dark; }
    html, body { margin: 0; min-height: 100%; background: #000; }
    body {
      font-family: Inter, system-ui, -apple-system, sans-serif;
      color: #ededed;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 24px;
    }
    .wrap { max-width: 560px; }
    .code {
      font-family: "Space Mono", monospace;
      font-size: 14px;
      letter-spacing: 0.14em;
      text-transform: uppercase;
      color: #a855f7;
    }
    h1 {
      font-size: clamp(32px, 9vw, 56px);
      line-height: 1.05;
      margin: 12px 0 16px;
      background: linear-gradient(135deg, #a855f7, #3b82f6, #22d3ee);
      -webkit-background-clip: text;
      background-clip: text;
      -webkit-text-fill-color: transparent;
    }
    p { color: #888; line-height: 1.6; margin: 0 0 28px; }
    a { color: #c4b5fd; }
    .links { display: flex; flex-wrap: wrap; gap: 10px 20px; }
    .links a { text-decoration: none; font-size: 15px; }
    .links a:hover { text-decoration: underline; }
  </style>
</head>
<body>
  <div class="wrap">
    <div class="code">Error 404</div>
    <h1>This page wandered off.</h1>
    <p>The link may be broken or the page may have moved.</p>
    <div class="links" id="links">
      <a href="/">Back to the portfolio</a>
    </div>
  </div>
  <script>
    (function () {
      var parts = location.pathname.split("/").filter(Boolean);
      var last = (parts[parts.length - 1] || "").toLowerCase();
      if (last && /^[a-z0-9._~-]+$/.test(last)) parts.pop();
      var root = "/" + parts.join("/");
      if (root.charAt(root.length - 1) !== "/") root += "/";

      var routes = [
        ["About", "aboutme"],
        ["Experience", "experience"],
        ["Skills", "skills"],
        ["Projects", "projects"],
        ["Research", "research"],
        ["Open Source", "opensource"],
        ["Education", "education"],
        ["Certificates", "certificates"]
      ];

      var host = document.getElementById("links");
      host.textContent = "";
      var home = document.createElement("a");
      home.href = root;
      home.textContent = "Back to the portfolio";
      host.appendChild(home);
      routes.forEach(function (entry) {
        var a = document.createElement("a");
        a.href = root + entry[1];
        a.textContent = entry[0];
        host.appendChild(a);
      });
    })();
  </script>
</body>
</html>
`;
}

for (const [slug, meta] of Object.entries(ROUTES)) {
  writeFileSync(join(ROOT, slug, "index.html"), routeShim(slug, meta));
  console.log(`wrote ${slug}/index.html`);
}

writeFileSync(join(ROOT, "404.html"), notFoundPage());
console.log("wrote 404.html");

const urls = [
  ORIGIN + "/",
  ...Object.entries(ROUTES)
    .filter(([, meta]) => !meta.alias)
    .map(([slug]) => `${ORIGIN}/${slug}`),
];
const sitemap = `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${urls
  .map(
    (url, index) =>
      `  <url>\n    <loc>${url}</loc>\n    <changefreq>monthly</changefreq>\n    <priority>${index === 0 ? "1.0" : "0.8"}</priority>\n  </url>`
  )
  .join("\n")}
</urlset>
`;
writeFileSync(join(ROOT, "sitemap.xml"), sitemap);
console.log("wrote sitemap.xml");

const robots = `User-agent: *
Allow: /

Sitemap: ${ORIGIN}/sitemap.xml
`;
writeFileSync(join(ROOT, "robots.txt"), robots);
console.log("wrote robots.txt");
